import subprocess
import ftplib
import os

def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser', ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test'):
    ftp = ftplib.FTP()
    try:
        ftp.connect(ftp_server)
    except Exception as e:
        raise Exception(f"Failed to connect to FTP server {ftp_server}: {str(e)}")

    try:
        ftp.login(ftp_user, ftp_password)
    except Exception as e:
        try:
            ftp.quit()
        except Exception:
            pass
        raise Exception(f"Failed to log into FTP server {ftp_server} with user {ftp_user}: {str(e)}")

    try:
        ftp.cwd(ftp_dir)
    except Exception as e:
        try:
            ftp.quit()
        except Exception:
            pass
        raise Exception(f"Failed to change to directory {ftp_dir} on server {ftp_server}: {str(e)}")

    try:
        filenames = ftp.nlst()
    finally:
        try:
            ftp.quit()
        except Exception:
            pass

    attempted_downloads = []
    for filename in filenames:
        if not filename or filename in ('.', '..'):
            continue

        local_name = os.path.basename(filename.rstrip('/'))
        if not local_name:
            continue

        attempted_downloads.append(local_name)

        ftp_url = f"ftp://{ftp_server}{ftp_dir.rstrip('/')}/{local_name}"
        cmd = [
            "wget",
            "--user", ftp_user,
            "--password", ftp_password,
            ftp_url,
            "-O", local_name,
        ]
        subprocess.run(cmd, check=False)

    return attempted_downloads

import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    found = False

    for proc in psutil.process_iter(["name", "cmdline"]):
        try:
            name = proc.info.get("name")
            cmdline = proc.info.get("cmdline") or []

            if name == process_name or (cmdline and cmdline[0] == process_name):
                found = True
                proc.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue

    if found:
        time.sleep(0.5)
        subprocess.Popen([process_name])
        return f"Process found. Restarting {process_name}."
    else:
        subprocess.Popen([process_name])
        return f"Process not found. Starting {process_name}."
